import type {WorkflowNode,Escape,Position} from './types.js';
import type {DisplayValue,DisplayRow} from './results.js';
import {SOURCE,tierLabel,serviceLabel,zoneLabel} from './old-naledi.js';
const numeric=(key:string,label:string,value:number,min:number,max:number,step:number,help:string)=>`<div class="field"><label class="field-label" for="param-${key}">${label}</label><input id="param-${key}" data-param="${key}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"><small>${help}</small></div>`;
const choose=(key:string,label:string,value:string,options:[string,string][])=>`<div class="field"><label class="field-label" for="param-${key}">${label}</label><select id="param-${key}" data-param="${key}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></div>`;
export function oldInspector(n:WorkflowNode){
  const source=`<a class="source-link" href="${SOURCE}06-Gaborone-Health-Facilities.ipynb" target="_blank" rel="noopener">Source notebook · NB06 ↗</a>`;
  switch(n.type){
    case 'area':return `<div class="source-card"><span class="inspector-section">Study boundary</span><h3>Old Naledi</h3><p>Gaborone, Botswana</p><span class="tag">SOURCE GEOMETRY</span></div><div class="detail-row"><span>Coordinates</span><strong>Longitude / latitude · CRS84</strong></div><div class="detail-row"><span>Source snapshot</span><strong>7f183843</strong></div><p class="description">The actual neighborhood polygon bounds the generated sample locations. Facility search extends outside it so nearby services remain visible.</p><a class="source-link" href="${SOURCE}data-files/geojson/OldNaledi.geojson" target="_blank" rel="noopener">Boundary provenance ↗</a><div class="notice">This example contains no household or patient locations. Sample points are a regular demonstration grid.</div>`;
    case 'samples':return numeric('spacingM','Sample spacing (meters)',n.params.spacingM,150,1000,50,'Generate a regular grid and retain points inside Old Naledi. The spacing uses a local geographic approximation.')+`<div class="rule-preview">These are <b>sample locations</b>, not buildings, households, population counts, or TB cases.</div><p class="description">This widget stands in for the prepared residential-building layer until that source artifact is available.</p>`;
    case 'facilities':return numeric('radiusKm','Candidate search radius (km)',n.params.radiusKm,1,15,1,'Measured from the center of the study boundary’s bounding box. Affects the candidate set, not a travel-time catchment.')+`<div class="detail-row"><span>Bundled registry</span><strong>214 facilities</strong></div><p class="description">Retains source names, ownership, service type, and coordinates. Includes facilities beyond Old Naledi because service access crosses neighborhood boundaries.</p><a class="source-link" href="${SOURCE}data-files/geojson/GaboroneHealthFacilities.geojson" target="_blank" rel="noopener">Facility registry snapshot ↗</a><div class="notice">Historical source snapshot. Current opening status, equipment operation, and appointment availability are not verified.</div>`;
    case 'xpert':return `<span class="inspector-section">Evidence hierarchy</span><ol class="evidence-ladder"><li><b>Direct</b><span>Named Princess Marina Hospital evidence.</span></li><li><b>Contextual</b><span>Named Broadhurst II evidence or government hospital type.</span></li><li><b>Inferential</b><span>Government clinic or health-post assumptions.</span></li><li><b>No evidence</b><span>No applicable assignment; availability stays unknown.</span></li></ol><p class="description">N3 evaluates mutually exclusive named-facility and type rules. Stronger named evidence takes precedence. The source notebook’s assignments are reproduced, not independently revalidated.</p>${source}`;
    case 'access':return choose('minimumEvidence','Minimum evidence',n.params.minimumEvidence,[['direct','Direct only'],['contextual','Direct + contextual'],['inferential','Include inferential']])+choose('service','Diagnostic service',n.params.service,[['onsite','Onsite only'],['anyKnown','Include referral pathways']])+numeric('speedMPerMin','Walking speed proxy (m/min)',n.params.speedMPerMin,30,120,5,'Default 70 m/min follows the source helper. Time = straight-line meters ÷ speed.')+`<div class="notice">This is a straight-line access proxy. It does not account for street routes, barriers, waiting time, or specimen transport. Referral availability does not mean onsite testing.</div>`;
    case 'access_policy':return numeric('thresholdMin','Review above (proxy minutes)',n.params.thresholdMin,0,120,5,'Illustrative review setting. Equality stays within the threshold; missing eligible facilities remain unknown.')+`<div class="rule-preview">When proxy access time is <b>greater than ${n.params.thresholdMin} minutes</b>, flag the sample for review.<br>When no facility qualifies, report <b>insufficient data</b>.</div><p class="description">N3 also assigns fixed display zones: ≤5, 5–15, 15–30, and >30 minutes. These bands describe this demonstration; they are not a validated TB policy.</p>`;
    case 'facility_audit':return `<p class="description">Keep every candidate facility visible, including those excluded by the access filter. The register reports its service assignment, evidence tier, and supporting reference.</p><div class="rule-preview">Use this output to compare <b>what the source records</b> with <b>what the access analysis accepts</b>.</div>${source}`;
    default:return null;
  }
}
export function oldEvidence(output:DisplayValue,row:DisplayRow,esc:Escape){
  const entries=output.kind==='facility-evidence'?[
    ['Ownership',row.owner],['Source facility type',row.serviceType],['Service assignment',serviceLabel(row.service||'Unknown')],['Evidence tier',tierLabel(row.tier||'Unknown')],['Source reference',row.reference]
  ]:[['Sample basis','Generated grid location'],['Nearest qualifying facility',row.center?.name||'None'],['Straight-line distance',row.distanceKm===null?'Unknown':row.distanceKm!.toFixed(3)+' km'],['Proxy access time',row.minutes===null?'Unknown':row.minutes!.toFixed(2)+' min'],['Review threshold',output.thresholdMin+' min'],['Access zone',zoneLabel(row.zone||'Unknown')],['Evidence tier',row.center?tierLabel(row.center.tier||'None'):'Unknown'],['Service assignment',row.center?serviceLabel(row.center.service||'Unknown'):'Unknown'],['Source reference',row.center?.reference||'No qualifying facility'],['Eligible facilities',`${output.eligibleCount} of ${output.candidateCount}`]];
  return `<h2>${esc(row.name)}</h2><p class="description">${esc(row.explanation)}</p>${entries.map(([k,v])=>`<div class="detail-row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="rule-preview">Historical facility evidence and synthetic sample locations. Spatial proximity alone does not establish diagnostic availability.</div><a class="source-link" href="${SOURCE}06-Gaborone-Health-Facilities.ipynb" target="_blank" rel="noopener">Pinned source notebook ↗</a><div class="inspector-actions"><button id="inspect-rules" class="button small">View N3 & evidence ↗</button></div>`;
}
export function resultTable(output:DisplayValue|undefined,esc:Escape,statusLabel:(status:string|undefined)=>string){
  const rows=output?.rows||[],audit=output?.kind==='facility-evidence',access=output?.kind==='access';
  const columns=audit?['Facility','Service assignment','Evidence','Reference']:access?['Sample','Qualifying facility','Proxy minutes','Decision']:['Neighborhood','Nearest center','Distance','Decision'];
  const body=rows.map(r=>{
    const cells=audit?[r.name,serviceLabel(r.service||'Unknown'),tierLabel(r.tier||'Unknown'),r.reference]:[r.name,r.center?.name||'—',access?(r.minutes===null?'Unknown':r.minutes!.toFixed(1)+' min'):(r.distanceKm===null?'—':r.distanceKm!.toFixed(2)+' km'),statusLabel(r.status)];
    return `<tr tabindex="0" data-place="${esc(r.id)}">${cells.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`;
  }).join('');
  return {head:columns.map(c=>`<th>${c}</th>`).join(''),body};
}
export function bars(output:DisplayValue,esc:Escape,statusLabel:(status:string|undefined)=>string){
  const audit=output?.kind==='facility-evidence',access=output?.kind==='access',field=audit?'tier':access?'zone':'status';
  const keys=audit?['Direct','Contextual','Inferential','None']:access?['Within5','Within15','Within30','Over30','Unknown']:['Review','NoFlag','Unknown'];
  const label=audit?tierLabel:access?zoneLabel:statusLabel;
  const counts=keys.map(k=>output.rows.filter(r=>r[field]===k).length),max=Math.max(1,...counts);
  return `<p class="muted">${audit?'Facilities by evidence tier':access?'Generated sample locations by proxy access zone · not population counts':'Locations by decision'}</p>${keys.map((k,i)=>`<div class="bar-row"><span>${esc(label(k))}</span><div class="bar-track"><div style="width:${counts[i]/max*100}%"></div></div><b>${counts[i]}</b></div>`).join('')}`;
}
export function oldMap(output:DisplayValue,selected:string|null|undefined,esc:Escape,statusLabel:(status:string|undefined)=>string){
  const boundary=output.boundary!,polygons=boundary.type==='MultiPolygon'?boundary.coordinates:[boundary.coordinates];
  const outline=polygons.flat(2),points=[...outline,...output.rows.filter(r=>r.coordinates!).map(r=>r.coordinates!),...(output.centers||[]).filter(c=>c.geometry).map(c=>c.geometry!.coordinates)];
  const xs=points.map(p=>p![0]),ys=points.map(p=>p![1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),cos=Math.cos((ymin+ymax)/2*Math.PI/180);
  const scale=Math.min(720/Math.max((xmax-xmin)*cos,.001),225/Math.max(ymax-ymin,.001));
  const project=(p:Position)=>[425+(p[0]-(xmin+xmax)/2)*cos*scale,145-(p[1]-(ymin+ymax)/2)*scale];
  let svg='<rect width="850" height="295" fill="#f0f3e9"/><text x="18" y="22" style="letter-spacing:1px">OLD NALEDI · SOURCE BOUNDARY</text>';
  svg+=polygons.map(rings=>`<path d="${rings.map(ring=>'M'+ring.map(p=>project(p).join(',')).join('L')+'Z').join(' ')}" fill="#dbe8d6" stroke="#668870" stroke-width="1.5" fill-rule="evenodd"/>`).join('');
  if(['spatial-coverage','spatial-map'].includes(output.kind||''))svg=svg.replace('OLD NALEDI · SOURCE BOUNDARY','STUDY AREA · SPATIAL COVERAGE');
  const focus=output.rows.find(r=>'result:'+r.id===selected);
  if(focus?.center){svg+=`<path d="M${project(focus.coordinates!).join(',')}L${project(focus.center.coordinates!).join(',')}" stroke="#587d6c" stroke-dasharray="4 4"/>`;}
  for(const c of output.centers||[]){if(!c.geometry)continue;const [x,y]=project(c.geometry!.coordinates);svg+=`<rect x="${x-5}" y="${y-5}" width="10" height="10" fill="#315d57" stroke="white"/><text x="${x+9}" y="${y-8}">${esc(c.properties.name)}</text>`;}
  for(const r of output.rows){if(!r.coordinates!)continue;const [x,y]=project(r.coordinates!),label=['spatial-coverage','spatial-map'].includes(output.kind||'')?(r.excluded?'Excluded':r.relation):output.kind==='facility-evidence'?tierLabel(r.tier||'Unknown'):statusLabel(r.status);svg+=`<g class="location" role="button" tabindex="0" data-place="${esc(r.id)}" data-layer="${esc(r.sourceNodeId||'')}" aria-label="${esc(r.name)}, ${esc(label)}${r.layerLabel?', '+esc(r.layerLabel):''}"><title>${esc(r.name)} · ${esc(label)}${r.layerLabel?' · '+esc(r.layerLabel):''}</title><circle cx="${x}" cy="${y}" r="${focus?.id===r.id?7:4}" fill="${{Review:'#c18b4f',NoFlag:'#699178',Unknown:'#a89b87'}[r.status!]}" stroke="white" stroke-width="1.2"/></g>`;}
  return svg+`<text x="18" y="281" style="font-size:10px">${['spatial-coverage','spatial-map'].includes(output.kind||'')?'Select a point to review its relation to the study boundary':output.kind==='access'?'Grid samples · straight-line proxy · select a point for evidence':'Historical facility registry · source evidence assignments'}</text><text x="826" y="25" text-anchor="middle">N ↑</text>`;
}
